#pragma once
//
// RustBridge — runtime loader for exv_capi.dll (the exv-capi C ABI).
//
// Resolves exv_capi.dll from the same directory as this module (then the
// standard search path), LoadLibrary's it, and binds the exv_* exports.
// No import lib — pure runtime resolution.
//
// Types come from docs/exv-capi.h (on the include path via CMakeLists.txt; GENERATED by cbindgen from
// crates/exv-capi/src/capi.rs). The function-pointer aliases below are checked against that header's
// prototypes at compile time, so a changed Rust signature breaks THIS build instead of crashing at run time.

#include <windows.h>
#include <string>
#include <type_traits>
#include "exv-capi.h"

namespace exvae {

using ExvAbiVersionFn       = uint32_t (*)();
using ExvVersionFn          = int32_t (*)(ExvVersion*);
using ExvLastErrorFn        = const char* (*)();
using ExvSessionOpenFn      = int32_t (*)(const char*, ExvSession**);
using ExvSessionInfoFn      = int32_t (*)(const ExvSession*, ExvStreamInfo*);
using ExvSessionFrameInfoFn = int32_t (*)(const ExvSession*, uint32_t, ExvFrameInfo*);
using ExvSessionDecodeFn    = int32_t (*)(const ExvSession*, uint32_t, uint32_t, // fmt: u32 (Rust ABI), not enum-int
                                          uint8_t*, size_t, uint32_t, size_t*);
using ExvSessionCloseFn     = int32_t (*)(ExvSession*);
using ExvBufferDataFn       = const uint8_t* (*)(const ExvBuffer*);
using ExvBufferLenFn        = size_t (*)(const ExvBuffer*);
using ExvBufferFreeFn       = void (*)(ExvBuffer*);
using ExvWriteFileFn        = int32_t (*)(const char*, const uint8_t*, size_t);
using ExvEncodeRgbaFn       = int32_t (*)(const ExvEncParams*, const float*, size_t, ExvBuffer**, size_t*);
using ExvVencOpenFn         = int32_t (*)(const char*, const ExvEncParams*, const ExvMeta*, uint32_t, int32_t, ExvVideoEncoder**);
using ExvVencAddRgbaFn      = int32_t (*)(ExvVideoEncoder*, const float*, size_t);
using ExvVencFinishFn       = int32_t (*)(ExvVideoEncoder*, uint64_t*);
using ExvVencFreeFn         = void (*)(ExvVideoEncoder*);
using ExvSessionMetaFn      = int32_t (*)(const ExvSession*, ExvMeta*);
// Channel matrix (single-part): enumerate channel names + decode with a name->RGBA routing.
using ExvChannelCountFn     = int32_t (*)(const ExvSession*, uint32_t*);
using ExvChannelNameFn      = int32_t (*)(const ExvSession*, uint32_t, char*, size_t, size_t*);
using ExvDecodeMappedFn     = int32_t (*)(const ExvSession*, uint32_t, uint32_t, uint8_t*, size_t, uint32_t,
                                          const char*, const char*, const char*, const char*, size_t*);

// Each alias must be EXACTLY the type of the header prototype it binds (the header is generated from Rust).
#define EXV_CHECK_FN(Alias, fn)     static_assert(std::is_same_v<Alias, decltype(&fn)>, #fn ": bridge alias != exv-capi.h prototype")
EXV_CHECK_FN(ExvAbiVersionFn,       exv_abi_version);
EXV_CHECK_FN(ExvVersionFn,          exv_version);
EXV_CHECK_FN(ExvLastErrorFn,        exv_last_error_message);
EXV_CHECK_FN(ExvSessionOpenFn,      exv_session_open);
EXV_CHECK_FN(ExvSessionInfoFn,      exv_session_info);
EXV_CHECK_FN(ExvSessionFrameInfoFn, exv_session_frame_info);
EXV_CHECK_FN(ExvSessionDecodeFn,    exv_session_decode);
EXV_CHECK_FN(ExvSessionCloseFn,     exv_session_close);
EXV_CHECK_FN(ExvBufferDataFn,       exv_buffer_data);
EXV_CHECK_FN(ExvBufferLenFn,        exv_buffer_len);
EXV_CHECK_FN(ExvBufferFreeFn,       exv_buffer_free);
EXV_CHECK_FN(ExvWriteFileFn,        exv_write_file);
EXV_CHECK_FN(ExvEncodeRgbaFn,       exv_encode_rgba_f32);
EXV_CHECK_FN(ExvVencOpenFn,         exv_venc_open);
EXV_CHECK_FN(ExvVencAddRgbaFn,      exv_venc_add_rgba_f32);
EXV_CHECK_FN(ExvVencFinishFn,       exv_venc_finish);
EXV_CHECK_FN(ExvVencFreeFn,         exv_venc_free);
EXV_CHECK_FN(ExvSessionMetaFn,      exv_session_meta);
EXV_CHECK_FN(ExvChannelCountFn,     exv_session_channel_count);
EXV_CHECK_FN(ExvChannelNameFn,      exv_session_channel_name);
EXV_CHECK_FN(ExvDecodeMappedFn,     exv_session_decode_mapped_rgbaf32);
#undef EXV_CHECK_FN

// Anchor inside this module for GetModuleHandleExW FROM_ADDRESS.
static const int kModuleAnchor = 0;

struct RustBridge {
    HMODULE module = nullptr;
    std::string load_error;   // why the last Load() failed (for the host log)
    ExvAbiVersionFn       abi_version       = nullptr;
    ExvVersionFn          version           = nullptr;
    ExvLastErrorFn        last_error        = nullptr;
    ExvSessionOpenFn      session_open      = nullptr;
    ExvSessionInfoFn      session_info      = nullptr;
    ExvSessionFrameInfoFn session_frame_info= nullptr;
    ExvSessionDecodeFn    session_decode    = nullptr;
    ExvSessionCloseFn     session_close     = nullptr;
    ExvBufferDataFn       buffer_data       = nullptr;
    ExvBufferLenFn        buffer_len        = nullptr;
    ExvBufferFreeFn       buffer_free       = nullptr;
    ExvWriteFileFn        write_file        = nullptr;
    ExvEncodeRgbaFn       encode_rgba       = nullptr;
    ExvVencOpenFn         venc_open         = nullptr;
    ExvVencAddRgbaFn      venc_add_rgba     = nullptr;
    ExvVencFinishFn       venc_finish       = nullptr;
    ExvVencFreeFn         venc_free         = nullptr;
    ExvSessionMetaFn      session_meta      = nullptr;
    // Channel matrix (REQUIRED — the DLL and .aex are always rebuilt+deployed together, so there is
    // no version-skew to tolerate; these are in the `required` list below).
    ExvChannelCountFn     channel_count     = nullptr;
    ExvChannelNameFn      channel_name      = nullptr;
    ExvDecodeMappedFn     decode_mapped     = nullptr;

    // Loads exv_capi.dll from the SAME directory as this module and binds exports. There is
    // deliberately NO fallback to the default DLL search path (CWD/PATH): that is a DLL-planting
    // hole, and a plugin must run against the codec it was deployed with. Returns true only if the
    // ABI revision matches and every required symbol resolved; otherwise `load_error` says why.
    bool Load() {
        if (module) return true;
        load_error.clear();

        HMODULE self = nullptr;
        if (GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS |
                               GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                               reinterpret_cast<LPCWSTR>(&kModuleAnchor), &self)) {
            wchar_t self_path[MAX_PATH]{};
            if (GetModuleFileNameW(self, self_path, MAX_PATH) > 0) {
                std::wstring dir(self_path);
                const auto pos = dir.find_last_of(L"\\/");
                if (pos != std::wstring::npos) {
                    const std::wstring dll = dir.substr(0, pos + 1) + L"exv_capi.dll";
                    module = LoadLibraryW(dll.c_str());
                }
            }
        }
        if (!module) { load_error = "exv_capi.dll not found next to the plugin"; return false; }

        auto bind = [&](const char* name) { return GetProcAddress(module, name); };
        abi_version        = reinterpret_cast<ExvAbiVersionFn>(bind("exv_abi_version"));
        version            = reinterpret_cast<ExvVersionFn>(bind("exv_version"));
        last_error         = reinterpret_cast<ExvLastErrorFn>(bind("exv_last_error_message"));
        session_open       = reinterpret_cast<ExvSessionOpenFn>(bind("exv_session_open"));
        session_info       = reinterpret_cast<ExvSessionInfoFn>(bind("exv_session_info"));
        session_frame_info = reinterpret_cast<ExvSessionFrameInfoFn>(bind("exv_session_frame_info"));
        session_decode     = reinterpret_cast<ExvSessionDecodeFn>(bind("exv_session_decode"));
        session_close      = reinterpret_cast<ExvSessionCloseFn>(bind("exv_session_close"));
        buffer_data        = reinterpret_cast<ExvBufferDataFn>(bind("exv_buffer_data"));
        buffer_len         = reinterpret_cast<ExvBufferLenFn>(bind("exv_buffer_len"));
        buffer_free        = reinterpret_cast<ExvBufferFreeFn>(bind("exv_buffer_free"));
        write_file         = reinterpret_cast<ExvWriteFileFn>(bind("exv_write_file"));
        encode_rgba        = reinterpret_cast<ExvEncodeRgbaFn>(bind("exv_encode_rgba_f32"));
        venc_open          = reinterpret_cast<ExvVencOpenFn>(bind("exv_venc_open"));
        venc_add_rgba      = reinterpret_cast<ExvVencAddRgbaFn>(bind("exv_venc_add_rgba_f32"));
        venc_finish        = reinterpret_cast<ExvVencFinishFn>(bind("exv_venc_finish"));
        venc_free          = reinterpret_cast<ExvVencFreeFn>(bind("exv_venc_free"));
        session_meta       = reinterpret_cast<ExvSessionMetaFn>(bind("exv_session_meta"));
        channel_count      = reinterpret_cast<ExvChannelCountFn>(bind("exv_session_channel_count"));
        channel_name       = reinterpret_cast<ExvChannelNameFn>(bind("exv_session_channel_name"));
        decode_mapped      = reinterpret_cast<ExvDecodeMappedFn>(bind("exv_session_decode_mapped_rgbaf32"));

        // ABI revision gate: a stale DLL next to this plugin must be rejected up front, not crash on
        // a changed signature/struct.
        if (!abi_version || abi_version() != EXV_ABI_VERSION) {
            load_error = "exv_capi.dll ABI revision mismatch (plugin expects " + std::to_string(EXV_ABI_VERSION) +
                         ", dll reports " + (abi_version ? std::to_string(abi_version()) : std::string("none")) + ")";
            FreeLibrary(module);
            module = nullptr;
            return false;
        }

        // Validate EVERY symbol the plugin dereferences without a per-call null
        // guard. An old/partial exv_capi.dll that exports some but not all of
        // these would otherwise crash on first use (null function call) deep in
        // a decode/encode callback. One list, one source of truth.
        // (last_error and write_file are always invoked guarded, so they stay
        // optional — a DLL lacking only those still works, degrading gracefully.)
        const void* required[] = {
            reinterpret_cast<const void*>(version),
            reinterpret_cast<const void*>(session_open),
            reinterpret_cast<const void*>(session_info),
            reinterpret_cast<const void*>(session_frame_info),
            reinterpret_cast<const void*>(session_decode),
            reinterpret_cast<const void*>(session_close),
            reinterpret_cast<const void*>(buffer_data),
            reinterpret_cast<const void*>(buffer_len),
            reinterpret_cast<const void*>(buffer_free),
            reinterpret_cast<const void*>(encode_rgba),
            reinterpret_cast<const void*>(venc_open),
            reinterpret_cast<const void*>(venc_add_rgba),
            reinterpret_cast<const void*>(venc_finish),
            reinterpret_cast<const void*>(venc_free),
            reinterpret_cast<const void*>(session_meta),
            reinterpret_cast<const void*>(channel_count),
            reinterpret_cast<const void*>(channel_name),
            reinterpret_cast<const void*>(decode_mapped),
        };
        for (const void* fn : required) {
            if (!fn) {
                // Reject the partial DLL: unload so a later retry rebinds cleanly
                // (Load() short-circuits on a non-null `module`).
                load_error = "exv_capi.dll is missing a required export";
                FreeLibrary(module);
                module = nullptr;
                return false;
            }
        }
        return true;
    }

    // Explicit unload, called from the AE DeathHook. There is intentionally NO destructor doing
    // FreeLibrary: a static destructor runs at DLL_PROCESS_DETACH under the loader lock.
    void Unload() {
        if (module) { FreeLibrary(module); module = nullptr; }
    }
};

} // namespace exvae
